cat > /tmp/verify/verify3.js <<'EOF'
const { chromium } = require('playwright');
(async () => {
    const browser = await chromium.launch();
    const page = await browser.newPage();
    const logs = [];
    const net = [];
    page.on('console', m => logs.push(m.type() + ': ' + m.text().slice(0,200)));
    page.on('pageerror', err => logs.push('pageerror: ' + err.message));
    page.on('request', r => { if (r.url().includes('9200') || r.url().includes('proxy')) net.push('REQ ' + r.method() + ' ' + r.url()); });
    page.on('response', async r => { if (r.url().includes('9200') || r.url().includes('proxy')) { let b=''; try { b = (await r.text()).slice(0,200);} catch(e){} net.push('RES ' + r.status() + ' ' + r.url() + ' :: ' + b.replace(/\n/g,' ')); } });
    await page.goto('http://localhost/examples/spotify/indexSpotify.html', { waitUntil: 'networkidle' });
    await page.waitForTimeout(2500);
    await page.click('.oneCollapsibleItem.filter .collapsible-header');
    await page.waitForTimeout(500);
    await page.selectOption('#dataExplorerDataFields', 'artists.name');
    await page.waitForTimeout(1500);
    console.log('FILTER_BOX_OPTIONS: ' + JSON.stringify(await page.$eval('#dataExplorerDataFields', el => el.selectedOptions.length)));
    console.log('FILTER_DEST_HTML: ' + (await page.$eval('#filterDestination', el => el.innerHTML.slice(0,400)).catch(()=>'n/a')));
    await page.click('.oneCollapsibleItem.output .collapsible-header');
    await page.waitForTimeout(500);
    const select = await page.$('#outputControls select');
    await select.selectOption('simpleTable');
    await page.waitForTimeout(500);
    await page.click('#getResults');
    await page.waitForTimeout(8000);
    console.log('GRAPHICS: ' + (await page.$eval('#graphicsWrapper', el => el.innerHTML.slice(0,600)).catch(()=>'n/a')));
    console.log('FEEDBACK: ' + await page.$eval('#feedbackText', el => el.textContent).catch(()=>'n/a'));
    console.log('NET: ' + JSON.stringify(net.filter(x => x.includes('_search') || x.includes('proxy')), null, 1));
    console.log('LOGS: ' + JSON.stringify(logs.slice(0,15), null, 1));
    await browser.close();
})().catch(e => { console.error('VERIFY_FAILED', e.message); process.exit(1); });
EOF
cd /tmp/verify && node verify3.js 2>&1 | tail -50
